{\g{The new algorithm scores feasible bins using a power-law decay of the remaining capacity combined with a bonus for the tightest fit and a scaled penalty for opening a new empty bin.}
```python
def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    max_cap = np.max(bins)
    scores = np.where(rem >= 0, -np.power(rem + 1.0, 1.5), -np.inf)
    if np.any(bins == max_cap):
        empty_indices = np.where((bins == max_cap) & (rem >= 0))[0]
        if empty_indices.size > 0:
            scores[empty_indices[0]] = -2.5
    return scores
